     1→package object
     2→
     3→import "fmt"
     4→
     5→// Object is the base interface for all runtime objects
     6→type Object interface {
     7→	Inspect() string
     8→}
     9→
    10→// Integer represents an integer value
    11→type Integer struct {
    12→	Value int64
    13→}
    14→
    15→func (i *Integer) Inspect() string {
    16→	return fmt.Sprintf("%d", i.Value)
    17→}
    18→
    19→// Float represents a floating-point value
    20→type Float struct {
    21→	Value float64
    22→}
    23→
    24→func (f *Float) Inspect() string {
    25→	return fmt.Sprintf("%f", f.Value)
    26→}
    27→
    28→// String represents a string value
    29→type String struct {
    30→	Value string
    31→}
    32→
    33→func (s *String) Inspect() string {
    34→	return s.Value
    35→}
    36→
    37→// Boolean represents a boolean value
    38→type Boolean struct {
    39→	Value bool
    40→}
    41→
    42→func (b *Boolean) Inspect() string {
    43→	return fmt.Sprintf("%v", b.Value)
    44→}
    45→
    46→// Null represents a null/nil value
    47→type Null struct{}
    48→
    49→func (n *Null) Inspect() string {
    50→	return "null"
    51→}
    52→
    53→// Array represents an array value
    54→type Array struct {
    55→	Elements []Object
    56→}
    57→
    58→func (a *Array) Inspect() string {
    59→	result := "["
    60→	for i, elem := range a.Elements {
    61→		if i > 0 {
    62→			result += ", "
    63→		}
    64→		result += elem.Inspect()
    65→	}
    66→	result += "]"
    67→	return result
    68→}
    69→
    70→// Hash represents a hash/map value
    71→type Hash struct {
    72→	Pairs map[string]Object
    73→}
    74→
    75→func (h *Hash) Inspect() string {
    76→	result := "{"
    77→	first := true
    78→	for key, val := range h.Pairs {
    79→		if !first {
    80→			result += ", "
    81→		}
    82→		first = false
    83→		result += fmt.Sprintf("%s: %s", key, val.Inspect())
    84→	}
    85→	result += "}"
    86→	return result
    87→}
    88→
    89→// Function represents a function value
    90→type Function struct {
    91→	Name string
    92→}
    93→
    94→func (f *Function) Inspect() string {
    95→	return fmt.Sprintf("fn:%s", f.Name)
    96→}
