     1→package ast
     2→
     3→import (
     4→	"fmt"
     5→	"strings"
     6→
     7→	"github.com/kimjindol2025/freelang-go/pkg/token"
     8→)
     9→
    10→// Node is the base interface for all AST nodes
    11→type Node interface {
    12→	TokenLiteral() string
    13→	String() string
    14→}
    15→
    16→// Statement is an interface for statement nodes
    17→type Statement interface {
    18→	Node
    19→	statementNode()
    20→}
    21→
    22→// Expression is an interface for expression nodes
    23→type Expression interface {
    24→	Node
    25→	expressionNode()
    26→}
    27→
    28→// Program represents the root node of the AST
    29→type Program struct {
    30→	Statements []Statement
    31→}
    32→
    33→func (p *Program) TokenLiteral() string {
    34→	if len(p.Statements) > 0 {
    35→		return p.Statements[0].TokenLiteral()
    36→	}
    37→	return ""
    38→}
    39→
    40→func (p *Program) String() string {
    41→	var out strings.Builder
    42→	for _, s := range p.Statements {
    43→		out.WriteString(s.String())
    44→	}
    45→	return out.String()
    46→}
    47→
    48→// ========== Statements ==========
    49→
    50→// BlockStatement represents a block of statements
    51→type BlockStatement struct {
    52→	Token      token.Token // the '{' token
    53→	Statements []Statement
    54→}
    55→
    56→func (bs *BlockStatement) statementNode()       {}
    57→func (bs *BlockStatement) TokenLiteral() string { return bs.Token.Literal }
    58→func (bs *BlockStatement) String() string {
    59→	var out strings.Builder
    60→	out.WriteString("{\n")
    61→	for _, s := range bs.Statements {
    62→		out.WriteString("  " + s.String())
    63→	}
    64→	out.WriteString("\n}")
    65→	return out.String()
    66→}
    67→
    68→// ExpressionStatement wraps an expression as a statement
    69→type ExpressionStatement struct {
    70→	Token      token.Token // first token of the expression
    71→	Expression Expression
    72→}
    73→
    74→func (es *ExpressionStatement) statementNode()       {}
    75→func (es *ExpressionStatement) TokenLiteral() string { return es.Token.Literal }
    76→func (es *ExpressionStatement) String() string {
    77→	if es.Expression != nil {
    78→		return es.Expression.String()
    79→	}
    80→	return ""
    81→}
    82→
    83→// ReturnStatement represents a return statement
    84→type ReturnStatement struct {
    85→	Token       token.Token // 'return' token
    86→	ReturnValue Expression
    87→}
    88→
    89→func (rs *ReturnStatement) statementNode()       {}
    90→func (rs *ReturnStatement) TokenLiteral() string { return rs.Token.Literal }
    91→func (rs *ReturnStatement) String() string {
    92→	var out strings.Builder
    93→	out.WriteString(rs.TokenLiteral() + " ")
    94→	if rs.ReturnValue != nil {
    95→		out.WriteString(rs.ReturnValue.String())
    96→	}
    97→	out.WriteString(";")
    98→	return out.String()
    99→}
   100→
   101→// LetStatement represents a let binding
   102→type LetStatement struct {
   103→	Token token.Token // 'let' token
   104→	Name  *Identifier
   105→	Value Expression
   106→}
   107→
   108→func (ls *LetStatement) statementNode()       {}
   109→func (ls *LetStatement) TokenLiteral() string { return ls.Token.Literal }
   110→func (ls *LetStatement) String() string {
   111→	var out strings.Builder
   112→	out.WriteString(ls.TokenLiteral() + " ")
   113→	out.WriteString(ls.Name.String())
   114→	out.WriteString(" = ")
   115→	if ls.Value != nil {
   116→		out.WriteString(ls.Value.String())
   117→	}
   118→	out.WriteString(";")
   119→	return out.String()
   120→}
   121→
   122→// IfStatement represents an if expression
   123→type IfStatement struct {
   124→	Token       token.Token // 'if' token
   125→	Condition   Expression
   126→	Consequence *BlockStatement
   127→	Alternative *BlockStatement
   128→}
   129→
   130→func (is *IfStatement) statementNode()       {}
   131→func (is *IfStatement) TokenLiteral() string { return is.Token.Literal }
   132→func (is *IfStatement) String() string {
   133→	var out strings.Builder
   134→	out.WriteString("if (")
   135→	out.WriteString(is.Condition.String())
   136→	out.WriteString(") ")
   137→	out.WriteString(is.Consequence.String())
   138→	if is.Alternative != nil {
   139→		out.WriteString(" else ")
   140→		out.WriteString(is.Alternative.String())
   141→	}
   142→	return out.String()
   143→}
   144→
   145→// ForStatement represents a for loop
   146→type ForStatement struct {
   147→	Token     token.Token // 'for' token
   148→	Iterable  Expression
   149→	Body      *BlockStatement
   150→	LoopVar   *Identifier
   151→}
   152→
   153→func (fs *ForStatement) statementNode()       {}
   154→func (fs *ForStatement) TokenLiteral() string { return fs.Token.Literal }
   155→func (fs *ForStatement) String() string {
   156→	var out strings.Builder
   157→	out.WriteString("for ")
   158→	if fs.LoopVar != nil {
   159→		out.WriteString(fs.LoopVar.String())
   160→		out.WriteString(" in ")
   161→	}
   162→	out.WriteString(fs.Iterable.String())
   163→	out.WriteString(" ")
   164→	out.WriteString(fs.Body.String())
   165→	return out.String()
   166→}
   167→
   168→// ========== Expressions ==========
   169→
   170→// Identifier represents a variable name
   171→type Identifier struct {
   172→	Token token.Token // IDENTIFIER token
   173→	Value string
   174→}
   175→
   176→func (i *Identifier) expressionNode()      {}
   177→func (i *Identifier) TokenLiteral() string { return i.Token.Literal }
   178→func (i *Identifier) String() string       { return i.Value }
   179→
   180→// IntegerLiteral represents an integer
   181→type IntegerLiteral struct {
   182→	Token token.Token // INT token
   183→	Value int64
   184→}
   185→
   186→func (il *IntegerLiteral) expressionNode()      {}
   187→func (il *IntegerLiteral) TokenLiteral() string { return il.Token.Literal }
   188→func (il *IntegerLiteral) String() string       { return il.Token.Literal }
   189→
   190→// StringLiteral represents a string
   191→type StringLiteral struct {
   192→	Token token.Token // STRING token
   193→	Value string
   194→}
   195→
   196→func (sl *StringLiteral) expressionNode()      {}
   197→func (sl *StringLiteral) TokenLiteral() string { return sl.Token.Literal }
   198→func (sl *StringLiteral) String() string       { return fmt.Sprintf("\"%s\"", sl.Value) }
   199→
   200→// BooleanLiteral represents a boolean
   201→type BooleanLiteral struct {
   202→	Token token.Token // BOOL token
   203→	Value bool
   204→}
   205→
   206→func (bl *BooleanLiteral) expressionNode()      {}
   207→func (bl *BooleanLiteral) TokenLiteral() string { return bl.Token.Literal }
   208→func (bl *BooleanLiteral) String() string       { return bl.Token.Literal }
   209→
   210→// ArrayLiteral represents an array
   211→type ArrayLiteral struct {
   212→	Token    token.Token // '[' token
   213→	Elements []Expression
   214→}
   215→
   216→func (al *ArrayLiteral) expressionNode()      {}
   217→func (al *ArrayLiteral) TokenLiteral() string { return al.Token.Literal }
   218→func (al *ArrayLiteral) String() string {
   219→	var out strings.Builder
   220→	out.WriteString("[")
   221→	for i, el := range al.Elements {
   222→		if i > 0 {
   223→			out.WriteString(", ")
   224→		}
   225→		out.WriteString(el.String())
   226→	}
   227→	out.WriteString("]")
   228→	return out.String()
   229→}
   230→
   231→// HashLiteral represents a hash/object
   232→type HashLiteral struct {
   233→	Token token.Token // '{' token
   234→	Pairs map[Expression]Expression
   235→}
   236→
   237→func (hl *HashLiteral) expressionNode()      {}
   238→func (hl *HashLiteral) TokenLiteral() string { return hl.Token.Literal }
   239→func (hl *HashLiteral) String() string {
   240→	var out strings.Builder
   241→	out.WriteString("{")
   242→	i := 0
   243→	for k, v := range hl.Pairs {
   244→		if i > 0 {
   245→			out.WriteString(", ")
   246→		}
   247→		out.WriteString(k.String())
   248→		out.WriteString(": ")
   249→		out.WriteString(v.String())
   250→		i++
   251→	}
   252→	out.WriteString("}")
   253→	return out.String()
   254→}
   255→
   256→// PrefixExpression represents a prefix operator expression
   257→type PrefixExpression struct {
   258→	Token    token.Token // prefix operator token
   259→	Operator string
   260→	Right    Expression
   261→}
   262→
   263→func (pe *PrefixExpression) expressionNode()      {}
   264→func (pe *PrefixExpression) TokenLiteral() string { return pe.Token.Literal }
   265→func (pe *PrefixExpression) String() string {
   266→	return fmt.Sprintf("(%s%s)", pe.Operator, pe.Right.String())
   267→}
   268→
   269→// InfixExpression represents an infix operator expression
   270→type InfixExpression struct {
   271→	Token    token.Token // infix operator token
   272→	Left     Expression
   273→	Operator string
   274→	Right    Expression
   275→}
   276→
   277→func (ie *InfixExpression) expressionNode()      {}
   278→func (ie *InfixExpression) TokenLiteral() string { return ie.Token.Literal }
   279→func (ie *InfixExpression) String() string {
   280→	return fmt.Sprintf("(%s %s %s)", ie.Left.String(), ie.Operator, ie.Right.String())
   281→}
   282→
   283→// FunctionLiteral represents a function literal
   284→type FunctionLiteral struct {
   285→	Token      token.Token // 'func' token
   286→	Parameters []*Identifier
   287→	Body       *BlockStatement
   288→}
   289→
   290→func (fl *FunctionLiteral) expressionNode()      {}
   291→func (fl *FunctionLiteral) TokenLiteral() string { return fl.Token.Literal }
   292→func (fl *FunctionLiteral) String() string {
   293→	var out strings.Builder
   294→	out.WriteString("func(")
   295→	for i, p := range fl.Parameters {
   296→		if i > 0 {
   297→			out.WriteString(", ")
   298→		}
   299→		out.WriteString(p.String())
   300→	}
   301→	out.WriteString(") ")
   302→	out.WriteString(fl.Body.String())
   303→	return out.String()
   304→}
   305→
   306→// CallExpression represents a function call
   307→type CallExpression struct {
   308→	Token     token.Token // '(' token
   309→	Function  Expression  // Identifier or FunctionLiteral
   310→	Arguments []Expression
   311→}
   312→
   313→func (ce *CallExpression) expressionNode()      {}
   314→func (ce *CallExpression) TokenLiteral() string { return ce.Token.Literal }
   315→func (ce *CallExpression) String() string {
   316→	var out strings.Builder
   317→	out.WriteString(ce.Function.String())
   318→	out.WriteString("(")
   319→	for i, arg := range ce.Arguments {
   320→		if i > 0 {
   321→			out.WriteString(", ")
   322→		}
   323→		out.WriteString(arg.String())
   324→	}
   325→	out.WriteString(")")
   326→	return out.String()
   327→}
   328→
   329→// IndexExpression represents array/hash indexing
   330→type IndexExpression struct {
   331→	Token token.Token // '[' token
   332→	Left  Expression
   333→	Index Expression
   334→}
   335→
   336→func (ie *IndexExpression) expressionNode()      {}
   337→func (ie *IndexExpression) TokenLiteral() string { return ie.Token.Literal }
   338→func (ie *IndexExpression) String() string {
   339→	return fmt.Sprintf("(%s[%s])", ie.Left.String(), ie.Index.String())
   340→}
   341→
   342→// AssignmentExpression represents an assignment
   343→type AssignmentExpression struct {
   344→	Token token.Token // '=' token
   345→	Left  Expression
   346→	Value Expression
   347→}
   348→
   349→func (ae *AssignmentExpression) expressionNode()      {}
   350→func (ae *AssignmentExpression) TokenLiteral() string { return ae.Token.Literal }
   351→func (ae *AssignmentExpression) String() string {
   352→	return fmt.Sprintf("(%s = %s)", ae.Left.String(), ae.Value.String())
   353→}
