     1→package lexer
     2→
     3→import (
     4→	"github.com/kimjindol2025/freelang-go/pkg/token"
     5→)
     6→
     7→// Lexer tokenizes FreeLang source code
     8→type Lexer struct {
     9→	input        string
    10→	position     int  // current position in input
    11→	readPosition int  // next position to read
    12→	ch           byte // current char
    13→	line         int
    14→	column       int
    15→}
    16→
    17→// New creates a new lexer
    18→func New(input string) *Lexer {
    19→	l := &Lexer{
    20→		input:  input,
    21→		line:   1,
    22→		column: 0,
    23→	}
    24→	l.readChar()
    25→	return l
    26→}
    27→
    28→// readChar reads the next character
    29→func (l *Lexer) readChar() {
    30→	if l.readPosition >= len(l.input) {
    31→		l.ch = 0 // EOF
    32→	} else {
    33→		l.ch = l.input[l.readPosition]
    34→	}
    35→	l.position = l.readPosition
    36→	l.readPosition++
    37→	l.column++
    38→
    39→	if l.ch == '\n' {
    40→		l.line++
    41→		l.column = 0
    42→	}
    43→}
    44→
    45→// peekChar looks at next char without consuming
    46→func (l *Lexer) peekChar() byte {
    47→	if l.readPosition >= len(l.input) {
    48→		return 0
    49→	}
    50→	return l.input[l.readPosition]
    51→}
    52→
    53→// NextToken returns the next token
    54→func (l *Lexer) NextToken() token.Token {
    55→	l.skipWhitespace()
    56→
    57→	var tok token.Token
    58→
    59→	switch l.ch {
    60→	case 0:
    61→		tok = l.newToken(token.EOF, "")
    62→	case '(':
    63→		tok = l.newToken(token.LPAREN, "(")
    64→		l.readChar()
    65→	case ')':
    66→		tok = l.newToken(token.RPAREN, ")")
    67→		l.readChar()
    68→	case '{':
    69→		tok = l.newToken(token.LBRACE, "{")
    70→		l.readChar()
    71→	case '}':
    72→		tok = l.newToken(token.RBRACE, "}")
    73→		l.readChar()
    74→	case '[':
    75→		tok = l.newToken(token.LBRACKET, "[")
    76→		l.readChar()
    77→	case ']':
    78→		tok = l.newToken(token.RBRACKET, "]")
    79→		l.readChar()
    80→	case ',':
    81→		tok = l.newToken(token.COMMA, ",")
    82→		l.readChar()
    83→	case ';':
    84→		tok = l.newToken(token.SEMICOLON, ";")
    85→		l.readChar()
    86→	case ':':
    87→		tok = l.newToken(token.COLON, ":")
    88→		l.readChar()
    89→	case '.':
    90→		if l.peekChar() == '.' && l.position+2 < len(l.input) && l.input[l.position+2] == '.' {
    91→			tok = l.newToken(token.SPREAD, "...")
    92→			l.readChar()
    93→			l.readChar()
    94→			l.readChar()
    95→		} else {
    96→			tok = l.newToken(token.DOT, ".")
    97→			l.readChar()
    98→		}
    99→	case '?':
   100→		if l.peekChar() == '.' {
   101→			tok = l.newToken(token.OPTIONAL, "?.")
   102→			l.readChar()
   103→			l.readChar()
   104→		} else {
   105→			tok = l.newToken(token.QUESTION, "?")
   106→			l.readChar()
   107→		}
   108→	case '+':
   109→		if l.peekChar() == '+' {
   110→			tok = l.newToken(token.INCREMENT, "++")
   111→			l.readChar()
   112→			l.readChar()
   113→		} else if l.peekChar() == '=' {
   114→			tok = l.newToken(token.PLUS_ASSIGN, "+=")
   115→			l.readChar()
   116→			l.readChar()
   117→		} else {
   118→			tok = l.newToken(token.PLUS, "+")
   119→			l.readChar()
   120→		}
   121→	case '-':
   122→		if l.peekChar() == '-' {
   123→			tok = l.newToken(token.DECREMENT, "--")
   124→			l.readChar()
   125→			l.readChar()
   126→		} else if l.peekChar() == '=' {
   127→			tok = l.newToken(token.MINUS_ASSIGN, "-=")
   128→			l.readChar()
   129→			l.readChar()
   130→		} else if l.peekChar() == '>' {
   131→			tok = l.newToken(token.LAMBDA, "->")
   132→			l.readChar()
   133→			l.readChar()
   134→		} else {
   135→			tok = l.newToken(token.MINUS, "-")
   136→			l.readChar()
   137→		}
   138→	case '*':
   139→		if l.peekChar() == '*' {
   140→			tok = l.newToken(token.POWER, "**")
   141→			l.readChar()
   142→			l.readChar()
   143→		} else if l.peekChar() == '=' {
   144→			tok = l.newToken(token.MUL_ASSIGN, "*=")
   145→			l.readChar()
   146→			l.readChar()
   147→		} else {
   148→			tok = l.newToken(token.MULTIPLY, "*")
   149→			l.readChar()
   150→		}
   151→	case '/':
   152→		if l.peekChar() == '/' {
   153→			l.skipLineComment()
   154→			return l.NextToken()
   155→		} else if l.peekChar() == '*' {
   156→			l.skipBlockComment()
   157→			return l.NextToken()
   158→		} else if l.peekChar() == '=' {
   159→			tok = l.newToken(token.DIV_ASSIGN, "/=")
   160→			l.readChar()
   161→			l.readChar()
   162→		} else {
   163→			tok = l.newToken(token.DIVIDE, "/")
   164→			l.readChar()
   165→		}
   166→	case '%':
   167→		if l.peekChar() == '=' {
   168→			tok = l.newToken(token.MOD_ASSIGN, "%=")
   169→			l.readChar()
   170→			l.readChar()
   171→		} else {
   172→			tok = l.newToken(token.MODULO, "%")
   173→			l.readChar()
   174→		}
   175→	case '=':
   176→		if l.peekChar() == '=' {
   177→			tok = l.newToken(token.EQ, "==")
   178→			l.readChar()
   179→			l.readChar()
   180→		} else if l.peekChar() == '>' {
   181→			tok = l.newToken(token.ARROW, "=>")
   182→			l.readChar()
   183→			l.readChar()
   184→		} else {
   185→			tok = l.newToken(token.ASSIGN, "=")
   186→			l.readChar()
   187→		}
   188→	case '!':
   189→		if l.peekChar() == '=' {
   190→			tok = l.newToken(token.NOT_EQ, "!=")
   191→			l.readChar()
   192→			l.readChar()
   193→		} else {
   194→			tok = l.newToken(token.NOT, "!")
   195→			l.readChar()
   196→		}
   197→	case '<':
   198→		if l.peekChar() == '=' {
   199→			tok = l.newToken(token.LE, "<=")
   200→			l.readChar()
   201→			l.readChar()
   202→		} else if l.peekChar() == '<' {
   203→			tok = l.newToken(token.LSHIFT, "<<")
   204→			l.readChar()
   205→			l.readChar()
   206→		} else {
   207→			tok = l.newToken(token.LT, "<")
   208→			l.readChar()
   209→		}
   210→	case '>':
   211→		if l.peekChar() == '=' {
   212→			tok = l.newToken(token.GE, ">=")
   213→			l.readChar()
   214→			l.readChar()
   215→		} else if l.peekChar() == '>' {
   216→			tok = l.newToken(token.RSHIFT, ">>")
   217→			l.readChar()
   218→			l.readChar()
   219→		} else {
   220→			tok = l.newToken(token.GT, ">")
   221→			l.readChar()
   222→		}
   223→	case '&':
   224→		if l.peekChar() == '&' {
   225→			tok = l.newToken(token.AND, "&&")
   226→			l.readChar()
   227→			l.readChar()
   228→		} else {
   229→			tok = l.newToken(token.BIT_AND, "&")
   230→			l.readChar()
   231→		}
   232→	case '|':
   233→		if l.peekChar() == '|' {
   234→			tok = l.newToken(token.OR, "||")
   235→			l.readChar()
   236→			l.readChar()
   237→		} else {
   238→			tok = l.newToken(token.BIT_OR, "|")
   239→			l.readChar()
   240→		}
   241→	case '^':
   242→		tok = l.newToken(token.BIT_XOR, "^")
   243→		l.readChar()
   244→	case '~':
   245→		tok = l.newToken(token.BIT_NOT, "~")
   246→		l.readChar()
   247→	case '"', '\'', '`':
   248→		quote := l.ch
   249→		literal := l.readString(quote)
   250→		tok = token.Token{
   251→			Type:    token.STRING,
   252→			Literal: literal,
   253→			Line:    l.line,
   254→			Column:  l.column,
   255→		}
   256→	default:
   257→		if isLetter(l.ch) {
   258→			literal := l.readIdentifier()
   259→			typ := token.LookupIdent(literal)
   260→			tok = token.Token{
   261→				Type:    typ,
   262→				Literal: literal,
   263→				Line:    l.line,
   264→				Column:  l.column,
   265→			}
   266→		} else if isDigit(l.ch) {
   267→			literal := l.readNumber()
   268→			tok = token.Token{
   269→				Type:    token.INT,
   270→				Literal: literal,
   271→				Line:    l.line,
   272→				Column:  l.column,
   273→			}
   274→		} else {
   275→			tok = l.newToken(token.ILLEGAL, string(l.ch))
   276→			l.readChar()
   277→		}
   278→	}
   279→
   280→	return tok
   281→}
   282→
   283→func (l *Lexer) newToken(typ token.TokenType, literal string) token.Token {
   284→	return token.Token{
   285→		Type:    typ,
   286→		Literal: literal,
   287→		Line:    l.line,
   288→		Column:  l.column,
   289→	}
   290→}
   291→
   292→func (l *Lexer) skipWhitespace() {
   293→	for l.ch == ' ' || l.ch == '\t' || l.ch == '\r' || l.ch == '\n' {
   294→		l.readChar()
   295→	}
   296→}
   297→
   298→func (l *Lexer) skipLineComment() {
   299→	for l.ch != '\n' && l.ch != 0 {
   300→		l.readChar()
   301→	}
   302→}
   303→
   304→func (l *Lexer) skipBlockComment() {
   305→	for l.ch != 0 {
   306→		if l.ch == '*' && l.peekChar() == '/' {
   307→			l.readChar()
   308→			l.readChar()
   309→			break
   310→		}
   311→		l.readChar()
   312→	}
   313→}
   314→
   315→func (l *Lexer) readIdentifier() string {
   316→	start := l.position
   317→	for isLetter(l.ch) || isDigit(l.ch) || l.ch == '_' || l.ch == '$' {
   318→		l.readChar()
   319→	}
   320→	return l.input[start:l.position]
   321→}
   322→
   323→func (l *Lexer) readNumber() string {
   324→	start := l.position
   325→	hasDot := false
   326→
   327→	for isDigit(l.ch) || (l.ch == '.' && !hasDot) {
   328→		if l.ch == '.' {
   329→			hasDot = true
   330→		}
   331→		l.readChar()
   332→	}
   333→
   334→	// Scientific notation
   335→	if l.ch == 'e' || l.ch == 'E' {
   336→		l.readChar()
   337→		if l.ch == '+' || l.ch == '-' {
   338→			l.readChar()
   339→		}
   340→		for isDigit(l.ch) {
   341→			l.readChar()
   342→		}
   343→	}
   344→
   345→	return l.input[start:l.position]
   346→}
   347→
   348→func (l *Lexer) readString(quote byte) string {
   349→	l.readChar() // skip opening quote
   350→	var result []byte
   351→
   352→	for l.ch != quote && l.ch != 0 {
   353→		if l.ch == '\\' {
   354→			l.readChar()
   355→			switch l.ch {
   356→			case 'n':
   357→				result = append(result, '\n')
   358→			case 't':
   359→				result = append(result, '\t')
   360→			case 'r':
   361→				result = append(result, '\r')
   362→			case '\\':
   363→				result = append(result, '\\')
   364→			case byte(quote):
   365→				result = append(result, quote)
   366→			default:
   367→				result = append(result, '\\', l.ch)
   368→			}
   369→			l.readChar()
   370→		} else {
   371→			result = append(result, l.ch)
   372→			l.readChar()
   373→		}
   374→	}
   375→
   376→	if l.ch == quote {
   377→		l.readChar() // skip closing quote
   378→	}
   379→
   380→	return string(result)
   381→}
   382→
   383→func isLetter(ch byte) bool {
   384→	return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')
   385→}
   386→
   387→func isDigit(ch byte) bool {
   388→	return ch >= '0' && ch <= '9'
   389→}
   390→

