     1→package checker
     2→
     3→import (
     4→	"fmt"
     5→
     6→	"github.com/kimjindol2025/freelang-go/pkg/ast"
     7→)
     8→
     9→// Checker performs semantic analysis and type checking
    10→type Checker struct {
    11→	symtab *SymbolTable
    12→	errors []string
    13→}
    14→
    15→// New creates a new type checker
    16→func New() *Checker {
    17→	return &Checker{
    18→		symtab: NewSymbolTable(),
    19→		errors: []string{},
    20→	}
    21→}
    22→
    23→// Errors returns all type checking errors
    24→func (c *Checker) Errors() []string {
    25→	return c.errors
    26→}
    27→
    28→// GlobalScope returns the global symbol table
    29→func (c *Checker) GlobalScope() *SymbolTable {
    30→	return c.symtab
    31→}
    32→
    33→// Check performs type checking on the entire program
    34→func (c *Checker) Check(program *ast.Program) {
    35→	for _, stmt := range program.Statements {
    36→		c.checkStatement(stmt)
    37→	}
    38→}
    39→
    40→// checkStatement checks a statement
    41→func (c *Checker) checkStatement(stmt ast.Statement) Type {
    42→	switch s := stmt.(type) {
    43→	case *ast.LetStatement:
    44→		return c.checkLetStatement(s)
    45→	case *ast.ReturnStatement:
    46→		return c.checkReturnStatement(s)
    47→	case *ast.ExpressionStatement:
    48→		return c.checkExpressionStatement(s)
    49→	case *ast.IfStatement:
    50→		return c.checkIfStatement(s)
    51→	case *ast.ForStatement:
    52→		return c.checkForStatement(s)
    53→	case *ast.BlockStatement:
    54→		return c.checkBlockStatement(s)
    55→	default:
    56→		c.addError("unknown statement type: %T", stmt)
    57→		return TypeVoid
    58→	}
    59→}
    60→
    61→// checkLetStatement checks a let statement
    62→func (c *Checker) checkLetStatement(stmt *ast.LetStatement) Type {
    63→	// Check if variable already exists in current scope
    64→	if _, ok := c.symtab.ResolveLocal(stmt.Name.Value); ok {
    65→		c.addError("variable %q already defined in this scope", stmt.Name.Value)
    66→		return TypeVoid
    67→	}
    68→
    69→	// Infer type from value
    70→	valueType := c.checkExpression(stmt.Value)
    71→	if valueType == nil {
    72→		valueType = TypeAny
    73→	}
    74→
    75→	// Define the variable
    76→	c.symtab.Define(
    77→		stmt.Name.Value,
    78→		SymbolVariable,
    79→		valueType,
    80→		true, // mutable
    81→	)
    82→
    83→	return TypeVoid
    84→}
    85→
    86→// checkReturnStatement checks a return statement
    87→func (c *Checker) checkReturnStatement(stmt *ast.ReturnStatement) Type {
    88→	if stmt.ReturnValue == nil {
    89→		return TypeVoid
    90→	}
    91→
    92→	return c.checkExpression(stmt.ReturnValue)
    93→}
    94→
    95→// checkExpressionStatement checks an expression statement
    96→func (c *Checker) checkExpressionStatement(stmt *ast.ExpressionStatement) Type {
    97→	return c.checkExpression(stmt.Expression)
    98→}
    99→
   100→// checkIfStatement checks an if statement
   101→func (c *Checker) checkIfStatement(stmt *ast.IfStatement) Type {
   102→	// Check condition
   103→	condType := c.checkExpression(stmt.Condition)
   104→	if condType != nil && !TypesEqual(condType, TypeBool) && !TypesEqual(condType, TypeAny) {
   105→		c.addError("if condition must be boolean, got %s", condType.String())
   106→	}
   107→
   108→	// Check consequence
   109→	c.checkBlockStatement(stmt.Consequence)
   110→
   111→	// Check alternative
   112→	if stmt.Alternative != nil {
   113→		c.checkBlockStatement(stmt.Alternative)
   114→	}
   115→
   116→	return TypeVoid
   117→}
   118→
   119→// checkForStatement checks a for statement
   120→func (c *Checker) checkForStatement(stmt *ast.ForStatement) Type {
   121→	// Check iterable
   122→	iterableType := c.checkExpression(stmt.Iterable)
   123→
   124→	// Push new scope for loop variable
   125→	c.symtab.PushScope()
   126→
   127→	// Define loop variable
   128→	if stmt.LoopVar != nil {
   129→		var elementType Type = TypeAny
   130→
   131→		// If iterable is array, element type is array's element type
   132→		if arrayType, ok := iterableType.(*ArrayType); ok {
   133→			elementType = arrayType.ElementType
   134→		}
   135→
   136→		c.symtab.Define(
   137→			stmt.LoopVar.Value,
   138→			SymbolVariable,
   139→			elementType,
   140→			true,
   141→		)
   142→	}
   143→
   144→	// Check loop body
   145→	c.checkBlockStatement(stmt.Body)
   146→
   147→	// Pop loop scope
   148→	c.symtab.PopScope()
   149→
   150→	return TypeVoid
   151→}
   152→
   153→// checkBlockStatement checks a block statement
   154→func (c *Checker) checkBlockStatement(stmt *ast.BlockStatement) Type {
   155→	var lastType Type = TypeVoid
   156→
   157→	for _, s := range stmt.Statements {
   158→		lastType = c.checkStatement(s)
   159→	}
   160→
   161→	return lastType
   162→}
   163→
   164→// checkExpression checks an expression and returns its type
   165→func (c *Checker) checkExpression(expr ast.Expression) Type {
   166→	if expr == nil {
   167→		return TypeAny
   168→	}
   169→
   170→	switch e := expr.(type) {
   171→	case *ast.Identifier:
   172→		return c.checkIdentifier(e)
   173→	case *ast.IntegerLiteral:
   174→		return TypeInt
   175→	case *ast.StringLiteral:
   176→		return TypeString
   177→	case *ast.BooleanLiteral:
   178→		return TypeBool
   179→	case *ast.ArrayLiteral:
   180→		return c.checkArrayLiteral(e)
   181→	case *ast.HashLiteral:
   182→		return c.checkHashLiteral(e)
   183→	case *ast.FunctionLiteral:
   184→		return c.checkFunctionLiteral(e)
   185→	case *ast.PrefixExpression:
   186→		return c.checkPrefixExpression(e)
   187→	case *ast.InfixExpression:
   188→		return c.checkInfixExpression(e)
   189→	case *ast.CallExpression:
   190→		return c.checkCallExpression(e)
   191→	case *ast.IndexExpression:
   192→		return c.checkIndexExpression(e)
   193→	case *ast.AssignmentExpression:
   194→		return c.checkAssignmentExpression(e)
   195→	default:
   196→		c.addError("unknown expression type: %T", expr)
   197→		return TypeAny
   198→	}
   199→}
   200→
   201→// checkIdentifier checks an identifier
   202→func (c *Checker) checkIdentifier(expr *ast.Identifier) Type {
   203→	symbol, ok := c.symtab.Resolve(expr.Value)
   204→	if !ok {
   205→		c.addError("undefined variable: %q", expr.Value)
   206→		return TypeAny
   207→	}
   208→
   209→	if symbol.Type == nil {
   210→		return TypeAny
   211→	}
   212→
   213→	return symbol.Type
   214→}
   215→
   216→// checkArrayLiteral checks an array literal
   217→func (c *Checker) checkArrayLiteral(expr *ast.ArrayLiteral) Type {
   218→	if len(expr.Elements) == 0 {
   219→		return NewArrayType(TypeAny)
   220→	}
   221→
   222→	// Infer element type from first element
   223→	elementType := c.checkExpression(expr.Elements[0])
   224→
   225→	// Check that all elements have compatible type
   226→	for i, elem := range expr.Elements[1:] {
   227→		elemType := c.checkExpression(elem)
   228→		if !IsCompatible(elemType, elementType) {
   229→			c.addError("element %d has incompatible type: expected %s, got %s",
   230→				i+1, elementType.String(), elemType.String())
   231→		}
   232→	}
   233→
   234→	return NewArrayType(elementType)
   235→}
   236→
   237→// checkHashLiteral checks a hash literal
   238→func (c *Checker) checkHashLiteral(expr *ast.HashLiteral) Type {
   239→	if len(expr.Pairs) == 0 {
   240→		return NewHashType(TypeAny, TypeAny)
   241→	}
   242→
   243→	var keyType, valueType Type
   244→
   245→	for k, v := range expr.Pairs {
   246→		// For identifiers as keys, treat them as strings (object property keys)
   247→		var kt Type
   248→		if _, isIdent := k.(*ast.Identifier); isIdent {
   249→			kt = TypeString
   250→		} else {
   251→			kt = c.checkExpression(k)
   252→		}
   253→
   254→		vt := c.checkExpression(v)
   255→
   256→		if keyType == nil {
   257→			keyType = kt
   258→		} else if !IsCompatible(kt, keyType) {
   259→			c.addError("hash key has incompatible type: expected %s, got %s",
   260→				keyType.String(), kt.String())
   261→		}
   262→
   263→		if valueType == nil {
   264→			valueType = vt
   265→		} else if !IsCompatible(vt, valueType) {
   266→			c.addError("hash value has incompatible type: expected %s, got %s",
   267→				valueType.String(), vt.String())
   268→		}
   269→	}
   270→
   271→	if keyType == nil {
   272→		keyType = TypeAny
   273→	}
   274→	if valueType == nil {
   275→		valueType = TypeAny
   276→	}
   277→
   278→	return NewHashType(keyType, valueType)
   279→}
   280→
   281→// checkFunctionLiteral checks a function literal
   282→func (c *Checker) checkFunctionLiteral(expr *ast.FunctionLiteral) Type {
   283→	// Push new scope for function
   284→	c.symtab.PushScope()
   285→
   286→	// Define parameters
   287→	paramTypes := make([]Type, len(expr.Parameters))
   288→	for i, param := range expr.Parameters {
   289→		paramTypes[i] = TypeAny // Parameters are inferred as Any by default
   290→		c.symtab.Define(param.Value, SymbolParameter, TypeAny, false)
   291→	}
   292→
   293→	// Check function body
   294→	returnType := c.checkBlockStatement(expr.Body)
   295→	if returnType == nil {
   296→		returnType = TypeVoid
   297→	}
   298→
   299→	// Pop function scope
   300→	c.symtab.PopScope()
   301→
   302→	return NewFunctionType(paramTypes, returnType)
   303→}
   304→
   305→// checkPrefixExpression checks a prefix expression
   306→func (c *Checker) checkPrefixExpression(expr *ast.PrefixExpression) Type {
   307→	rightType := c.checkExpression(expr.Right)
   308→
   309→	switch expr.Operator {
   310→	case "!":
   311→		if !TypesEqual(rightType, TypeBool) && !TypesEqual(rightType, TypeAny) {
   312→			c.addError("! operator requires boolean, got %s", rightType.String())
   313→		}
   314→		return TypeBool
   315→	case "-":
   316→		if !TypesEqual(rightType, TypeInt) && !TypesEqual(rightType, TypeFloat) && !TypesEqual(rightType, TypeAny) {
   317→			c.addError("- operator requires number, got %s", rightType.String())
   318→		}
   319→		return rightType
   320→	case "+":
   321→		if !TypesEqual(rightType, TypeInt) && !TypesEqual(rightType, TypeFloat) && !TypesEqual(rightType, TypeAny) {
   322→			c.addError("+ operator requires number, got %s", rightType.String())
   323→		}
   324→		return rightType
   325→	case "~":
   326→		if !TypesEqual(rightType, TypeInt) && !TypesEqual(rightType, TypeAny) {
   327→			c.addError("~ operator requires int, got %s", rightType.String())
   328→		}
   329→		return TypeInt
   330→	default:
   331→		c.addError("unknown prefix operator: %s", expr.Operator)
   332→		return TypeAny
   333→	}
   334→}
   335→
   336→// checkInfixExpression checks an infix expression
   337→func (c *Checker) checkInfixExpression(expr *ast.InfixExpression) Type {
   338→	leftType := c.checkExpression(expr.Left)
   339→	rightType := c.checkExpression(expr.Right)
   340→
   341→	switch expr.Operator {
   342→	case "+":
   343→		// + works on same types (numbers with numbers, strings with strings)
   344→		if isNumber(leftType) && isNumber(rightType) {
   345→			return leftType
   346→		}
   347→		if TypesEqual(leftType, TypeString) && TypesEqual(rightType, TypeString) {
   348→			return leftType
   349→		}
   350→		c.addError("+ operator requires same types (numbers or strings), got %s and %s",
   351→			leftType.String(), rightType.String())
   352→		return leftType
   353→	case "-", "*", "/", "%":
   354→		// Arithmetic operators require numbers
   355→		if !isNumber(leftType) || !isNumber(rightType) {
   356→			c.addError("%s operator requires numbers, got %s and %s",
   357→				expr.Operator, leftType.String(), rightType.String())
   358→		}
   359→		return leftType
   360→	case "**":
   361→		// Power operator requires numbers
   362→		if !isNumber(leftType) || !isNumber(rightType) {
   363→			c.addError("** operator requires numbers, got %s and %s",
   364→				leftType.String(), rightType.String())
   365→		}
   366→		return leftType
   367→	case "==", "!=":
   368→		// Equality operators work on all types
   369→		return TypeBool
   370→	case "<", ">", "<=", ">=":
   371→		// Comparison operators require numbers
   372→		if !isNumber(leftType) || !isNumber(rightType) {
   373→			c.addError("%s operator requires numbers, got %s and %s",
   374→				expr.Operator, leftType.String(), rightType.String())
   375→		}
   376→		return TypeBool
   377→	case "&&", "||":
   378→		// Logical operators require booleans
   379→		if !TypesEqual(leftType, TypeBool) || !TypesEqual(rightType, TypeBool) {
   380→			c.addError("%s operator requires booleans, got %s and %s",
   381→				expr.Operator, leftType.String(), rightType.String())
   382→		}
   383→		return TypeBool
   384→	case "&", "|", "^":
   385→		// Bitwise operators require integers
   386→		if !TypesEqual(leftType, TypeInt) || !TypesEqual(rightType, TypeInt) {
   387→			c.addError("%s operator requires integers, got %s and %s",
   388→				expr.Operator, leftType.String(), rightType.String())
   389→		}
   390→		return TypeInt
   391→	case "<<", ">>":
   392→		// Shift operators require integers
   393→		if !TypesEqual(leftType, TypeInt) || !TypesEqual(rightType, TypeInt) {
   394→			c.addError("%s operator requires integers, got %s and %s",
   395→				expr.Operator, leftType.String(), rightType.String())
   396→		}
   397→		return TypeInt
   398→	default:
   399→		c.addError("unknown infix operator: %s", expr.Operator)
   400→		return TypeAny
   401→	}
   402→}
   403→
   404→// checkCallExpression checks a function call
   405→func (c *Checker) checkCallExpression(expr *ast.CallExpression) Type {
   406→	funcType := c.checkExpression(expr.Function)
   407→
   408→	if funcType == nil {
   409→		return TypeAny
   410→	}
   411→
   412→	// Function type check
   413→	if funcType, ok := funcType.(*FunctionType); ok {
   414→		// Check argument count
   415→		if len(expr.Arguments) != len(funcType.ParameterTypes) {
   416→			c.addError("function call expects %d arguments, got %d",
   417→				len(funcType.ParameterTypes), len(expr.Arguments))
   418→		}
   419→
   420→		// Check argument types
   421→		for i, arg := range expr.Arguments {
   422→			argType := c.checkExpression(arg)
   423→			if i < len(funcType.ParameterTypes) {
   424→				if !IsCompatible(argType, funcType.ParameterTypes[i]) {
   425→					c.addError("argument %d has wrong type: expected %s, got %s",
   426→						i, funcType.ParameterTypes[i].String(), argType.String())
   427→				}
   428→			}
   429→		}
   430→
   431→		return funcType.ReturnType
   432→	}
   433→
   434→	c.addError("calling non-function type: %s", funcType.String())
   435→	return TypeAny
   436→}
   437→
   438→// checkIndexExpression checks an index expression
   439→func (c *Checker) checkIndexExpression(expr *ast.IndexExpression) Type {
   440→	leftType := c.checkExpression(expr.Left)
   441→	indexType := c.checkExpression(expr.Index)
   442→
   443→	switch left := leftType.(type) {
   444→	case *ArrayType:
   445→		if !TypesEqual(indexType, TypeInt) && !TypesEqual(indexType, TypeAny) {
   446→			c.addError("array index must be int, got %s", indexType.String())
   447→		}
   448→		return left.ElementType
   449→
   450→	case *HashType:
   451→		if !IsCompatible(indexType, left.KeyType) {
   452→			c.addError("hash key has wrong type: expected %s, got %s",
   453→				left.KeyType.String(), indexType.String())
   454→		}
   455→		return left.ValueType
   456→
   457→	default:
   458→		c.addError("cannot index type %s", leftType.String())
   459→		return TypeAny
   460→	}
   461→}
   462→
   463→// checkAssignmentExpression checks an assignment expression
   464→func (c *Checker) checkAssignmentExpression(expr *ast.AssignmentExpression) Type {
   465→	// Get target type
   466→	var targetType Type
   467→
   468→	if ident, ok := expr.Left.(*ast.Identifier); ok {
   469→		symbol, ok := c.symtab.Resolve(ident.Value)
   470→		if !ok {
   471→			c.addError("undefined variable: %q", ident.Value)
   472→			return TypeAny
   473→		}
   474→
   475→		if !symbol.Mutable {
   476→			c.addError("cannot assign to immutable variable: %q", ident.Value)
   477→			return TypeAny
   478→		}
   479→
   480→		targetType = symbol.Type
   481→	} else {
   482→		// For complex assignments (array[i] = value, obj.prop = value), infer from value
   483→		targetType = c.checkExpression(expr.Left)
   484→	}
   485→
   486→	// Check value type compatibility
   487→	valueType := c.checkExpression(expr.Value)
   488→	if !IsCompatible(valueType, targetType) {
   489→		c.addError("cannot assign %s to %s", valueType.String(), targetType.String())
   490→	}
   491→
   492→	return targetType
   493→}
   494→
   495→// Helper functions
   496→
   497→func isNumber(t Type) bool {
   498→	return TypesEqual(t, TypeInt) || TypesEqual(t, TypeFloat) || TypesEqual(t, TypeAny)
   499→}
   500→
   501→func (c *Checker) addError(format string, args ...interface{}) {
   502→	c.errors = append(c.errors, fmt.Sprintf(format, args...))
   503→}
