    12→// Precedence constants for operator precedence parsing
    13→const (
    14→	LOWEST = iota
    15→	ASSIGN
    16→	OR
    17→	AND
    18→	EQUALS
    19→	COMPARE
    20→	TERM
    21→	FACTOR
    22→	PREFIX
    23→	CALL
    24→	INDEX
    25→)
    26→
    27→var precedences = map[token.TokenType]int{
    28→	token.ASSIGN:       ASSIGN,
    29→	token.PLUS_ASSIGN:  ASSIGN,
    30→	token.MINUS_ASSIGN: ASSIGN,
    31→	token.MUL_ASSIGN:   ASSIGN,
    32→	token.DIV_ASSIGN:   ASSIGN,
    33→	token.MOD_ASSIGN:   ASSIGN,
    34→	token.OR:           OR,
    35→	token.AND:          AND,
    36→	token.EQ:           EQUALS,
    37→	token.NOT_EQ:       EQUALS,
    38→	token.LT:           COMPARE,
    39→	token.LE:           COMPARE,
    40→	token.GT:           COMPARE,
    41→	token.GE:           COMPARE,
    42→	token.PLUS:         TERM,
    43→	token.MINUS:        TERM,
    44→	token.MULTIPLY:     FACTOR,
    45→	token.DIVIDE:       FACTOR,
    46→	token.MODULO:       FACTOR,
    47→	token.POWER:        FACTOR,
    48→	token.LSHIFT:       COMPARE,
    49→	token.RSHIFT:       COMPARE,
    50→	token.BIT_AND:      EQUALS,
    51→	token.BIT_OR:       EQUALS,
    52→	token.BIT_XOR:      EQUALS,
    53→	token.DOT:          CALL,
    54→	token.LBRACKET:     INDEX,
    55→	token.LPAREN:       CALL,
    56→}
    57→
    58→// Parser tokenizes and parses FreeLang code
    59→type Parser struct {
    60→	l      *lexer.Lexer
    61→	errors []string
    62→
    63→	curToken  token.Token
    64→	peekToken token.Token
    65→
    66→	prefixParseFns map[token.TokenType]prefixParseFn
    67→	infixParseFns  map[token.TokenType]infixParseFn
    68→}
    69→
    70→type prefixParseFn func() ast.Expression
    71→type infixParseFn func(ast.Expression) ast.Expression
    72→
    73→// New creates a new parser
    74→func New(l *lexer.Lexer) *Parser {
    75→	p := &Parser{
    76→		l:      l,
    77→		errors: []string{},
    78→	}
    79→
    80→	p.prefixParseFns = make(map[token.TokenType]prefixParseFn)
    81→	p.prefixParseFns[token.IDENTIFIER] = p.parseIdentifier
    82→	p.prefixParseFns[token.INT] = p.parseIntegerLiteral
    83→	p.prefixParseFns[token.STRING] = p.parseStringLiteral
    84→	p.prefixParseFns[token.BOOL] = p.parseBooleanLiteral
    85→	p.prefixParseFns[token.LBRACKET] = p.parseArrayLiteral
    86→	p.prefixParseFns[token.LBRACE] = p.parseHashLiteral
    87→	p.prefixParseFns[token.LPAREN] = p.parseGroupedExpression
    88→	p.prefixParseFns[token.FUNC] = p.parseFunctionLiteral
    89→	p.prefixParseFns[token.NOT] = p.parsePrefixExpression
    90→	p.prefixParseFns[token.MINUS] = p.parsePrefixExpression
    91→	p.prefixParseFns[token.PLUS] = p.parsePrefixExpression
    92→	p.prefixParseFns[token.BIT_NOT] = p.parsePrefixExpression
    93→	p.prefixParseFns[token.INCREMENT] = p.parsePrefixExpression
    94→	p.prefixParseFns[token.DECREMENT] = p.parsePrefixExpression
    95→
    96→	p.infixParseFns = make(map[token.TokenType]infixParseFn)
    97→	p.infixParseFns[token.PLUS] = p.parseInfixExpression
    98→	p.infixParseFns[token.MINUS] = p.parseInfixExpression
    99→	p.infixParseFns[token.MULTIPLY] = p.parseInfixExpression
   100→	p.infixParseFns[token.DIVIDE] = p.parseInfixExpression
   101→	p.infixParseFns[token.MODULO] = p.parseInfixExpression
   102→	p.infixParseFns[token.POWER] = p.parseInfixExpression
   103→	p.infixParseFns[token.EQ] = p.parseInfixExpression
   104→	p.infixParseFns[token.NOT_EQ] = p.parseInfixExpression
   105→	p.infixParseFns[token.LT] = p.parseInfixExpression
   106→	p.infixParseFns[token.LE] = p.parseInfixExpression
   107→	p.infixParseFns[token.GT] = p.parseInfixExpression
   108→	p.infixParseFns[token.GE] = p.parseInfixExpression
   109→	p.infixParseFns[token.AND] = p.parseInfixExpression
   110→	p.infixParseFns[token.OR] = p.parseInfixExpression
   111→	p.infixParseFns[token.BIT_AND] = p.parseInfixExpression
   112→	p.infixParseFns[token.BIT_OR] = p.parseInfixExpression
   113→	p.infixParseFns[token.BIT_XOR] = p.parseInfixExpression
   114→	p.infixParseFns[token.LSHIFT] = p.parseInfixExpression
   115→	p.infixParseFns[token.RSHIFT] = p.parseInfixExpression
   116→	p.infixParseFns[token.ASSIGN] = p.parseAssignmentExpression
   117→	p.infixParseFns[token.PLUS_ASSIGN] = p.parseAssignmentExpression
   118→	p.infixParseFns[token.MINUS_ASSIGN] = p.parseAssignmentExpression
   119→	p.infixParseFns[token.MUL_ASSIGN] = p.parseAssignmentExpression
   120→	p.infixParseFns[token.DIV_ASSIGN] = p.parseAssignmentExpression
   121→	p.infixParseFns[token.MOD_ASSIGN] = p.parseAssignmentExpression
   122→	p.infixParseFns[token.LBRACKET] = p.parseIndexExpression
   123→	p.infixParseFns[token.LPAREN] = p.parseCallExpression
   124→	p.infixParseFns[token.DOT] = p.parseDotExpression
   125→
   126→	// Read two tokens, so curToken and peekToken are both set
   127→	p.nextToken()
   128→	p.nextToken()
