   133→// Errors returns parser errors
   134→func (p *Parser) Errors() []string {
   135→	return p.errors
   136→}
   137→
   138→// CurToken returns current token (for debugging)
   139→func (p *Parser) CurToken() token.Token {
   140→	return p.curToken
   141→}
   142→
   143→// PeekToken returns next token (for debugging)
   144→func (p *Parser) PeekToken() token.Token {
   145→	return p.peekToken
   146→}
   147→
   148→// nextToken advances to next token
   149→func (p *Parser) nextToken() {
   150→	p.curToken = p.peekToken
   151→	p.peekToken = p.l.NextToken()
   152→}
   153→
   154→// ParseProgram parses the entire program
   155→func (p *Parser) ParseProgram() *ast.Program {
   156→	program := &ast.Program{
   157→		Statements: []ast.Statement{},
   158→	}
   159→
   160→	for p.curToken.Type != token.EOF {
   161→		stmt := p.parseStatement()
   162→		if stmt != nil {
   163→			program.Statements = append(program.Statements, stmt)
   164→		}
   165→		p.nextToken()
   166→	}
   167→
   168→	return program
   169→}
   170→
   171→// parseStatement parses a statement
   172→func (p *Parser) parseStatement() ast.Statement {
   173→	switch p.curToken.Type {
   174→	case token.LET:
   175→		return p.parseLetStatement()
   176→	case token.RETURN:
   177→		return p.parseReturnStatement()
   178→	case token.IF:
   179→		return p.parseIfStatement()
   180→	case token.FOR:
   181→		return p.parseForStatement()
   182→	default:
   183→		return p.parseExpressionStatement()
   184→	}
   185→}
   186→
   187→// parseLetStatement parses let x = 5;
   188→func (p *Parser) parseLetStatement() *ast.LetStatement {
   189→	stmt := &ast.LetStatement{
   190→		Token: p.curToken,
   191→	}
   192→
   193→	if !p.expectPeek(token.IDENTIFIER) {
   194→		return nil
   195→	}
   196→
   197→	stmt.Name = &ast.Identifier{
   198→		Token: p.curToken,
   199→		Value: p.curToken.Literal,
   200→	}
   201→
   202→	if !p.expectPeek(token.ASSIGN) {
   203→		return nil
   204→	}
   205→
   206→	p.nextToken()
   207→	stmt.Value = p.parseExpression(LOWEST)
   208→
   209→	if p.peekToken.Type == token.SEMICOLON {
   210→		p.nextToken()
   211→	}
   212→
   213→	return stmt
   214→}
   215→
   216→// parseReturnStatement parses return expression;
   217→func (p *Parser) parseReturnStatement() *ast.ReturnStatement {
   218→	stmt := &ast.ReturnStatement{
   219→		Token: p.curToken,
   220→	}
   221→
   222→	p.nextToken()
   223→	stmt.ReturnValue = p.parseExpression(LOWEST)
   224→
   225→	if p.peekToken.Type == token.SEMICOLON {
   226→		p.nextToken()
   227→	}
   228→
   229→	return stmt
   230→}
   231→
   232→// parseIfStatement parses if (condition) { block } else { block }
   233→func (p *Parser) parseIfStatement() *ast.IfStatement {
   234→	stmt := &ast.IfStatement{
   235→		Token: p.curToken,
   236→	}
   237→
   238→	if !p.expectPeek(token.LPAREN) {
   239→		return nil
   240→	}
   241→
   242→	p.nextToken()
   243→	stmt.Condition = p.parseExpression(LOWEST)
   244→
   245→	if !p.expectPeek(token.RPAREN) {
   246→		return nil
   247→	}
   248→
   249→	if !p.expectPeek(token.LBRACE) {
   250→		return nil
   251→	}
   252→
   253→	stmt.Consequence = p.parseBlockStatement()
   254→
   255→	if p.peekToken.Type == token.ELSE {
   256→		p.nextToken()
   257→
   258→		if !p.expectPeek(token.LBRACE) {
   259→			return nil
   260→		}
   261→
   262→		stmt.Alternative = p.parseBlockStatement()
   263→	}
   264→
   265→	return stmt
   266→}
   267→
   268→// parseForStatement parses for var in iterable { block }
   269→func (p *Parser) parseForStatement() *ast.ForStatement {
   270→	stmt := &ast.ForStatement{
   271→		Token: p.curToken,
   272→	}
   273→
   274→	p.nextToken()
   275→
   276→	// Check if there's a loop variable (for x in ...)
   277→	if p.curToken.Type == token.IDENTIFIER && p.peekToken.Type == token.IN {
   278→		stmt.LoopVar = &ast.Identifier{
   279→			Token: p.curToken,
   280→			Value: p.curToken.Literal,
   281→		}
   282→		p.nextToken() // consume 'in'
   283→		p.nextToken() // move to iterable
   284→	}
   285→
   286→	stmt.Iterable = p.parseExpression(LOWEST)
   287→
   288→	if !p.expectPeek(token.LBRACE) {
   289→		return nil
   290→	}
   291→
   292→	stmt.Body = p.parseBlockStatement()
   293→
   294→	return stmt
   295→}
   296→
   297→// parseBlockStatement parses { statement; statement; }
   298→func (p *Parser) parseBlockStatement() *ast.BlockStatement {
   299→	block := &ast.BlockStatement{
   300→		Token:      p.curToken,
   301→		Statements: []ast.Statement{},
   302→	}
   303→
   304→	p.nextToken()
   305→
   306→	for p.curToken.Type != token.RBRACE && p.curToken.Type != token.EOF {
   307→		stmt := p.parseStatement()
   308→		if stmt != nil {
   309→			block.Statements = append(block.Statements, stmt)
   310→		}
   311→		p.nextToken()
   312→	}
   313→
   314→	return block
   315→}
   316→
   317→// parseExpressionStatement parses an expression as a statement
   318→func (p *Parser) parseExpressionStatement() *ast.ExpressionStatement {
   319→	stmt := &ast.ExpressionStatement{
   320→		Token:      p.curToken,
   321→		Expression: p.parseExpression(LOWEST),
   322→	}
   323→
   324→	if p.peekToken.Type == token.SEMICOLON {
   325→		p.nextToken()
   326→	}
   327→
   328→	return stmt
   329→}
   330→
   331→// parseExpression parses expressions with operator precedence
   332→func (p *Parser) parseExpression(precedence int) ast.Expression {
   333→	prefixFn := p.prefixParseFns[p.curToken.Type]
   334→	if prefixFn == nil {
   335→		p.errors = append(p.errors, fmt.Sprintf("no prefix parse function for %s", p.curToken.Type))
   336→		return nil
   337→	}
   338→
   339→	leftExp := prefixFn()
   340→
   341→	for precedence < p.peekPrecedence() {
   342→		infixFn := p.infixParseFns[p.peekToken.Type]
   343→		if infixFn == nil {
   344→			return leftExp
   345→		}
   346→
   347→		p.nextToken()
   348→		leftExp = infixFn(leftExp)
   349→	}
   350→
   351→	return leftExp
   352→}
   353→
   354→// parsePrefixExpression parses -5, !true, etc.
   355→func (p *Parser) parsePrefixExpression() ast.Expression {
   356→	expr := &ast.PrefixExpression{
   357→		Token:    p.curToken,
   358→		Operator: p.curToken.Literal,
   359→	}
   360→
   361→	p.nextToken()
   362→	expr.Right = p.parseExpression(PREFIX)
   363→
   364→	return expr
   365→}
   366→
   367→// parseInfixExpression parses a + b, a == b, etc.
   368→func (p *Parser) parseInfixExpression(left ast.Expression) ast.Expression {
   369→	expr := &ast.InfixExpression{
   370→		Token:    p.curToken,
   371→		Operator: p.curToken.Literal,
   372→		Left:     left,
   373→	}
   374→
   375→	precedence := p.curPrecedence()
   376→	p.nextToken()
   377→	expr.Right = p.parseExpression(precedence)
   378→
   379→	return expr
   380→}
