   493→// parseHashLiteral parses {key: value, key: value}
   494→func (p *Parser) parseHashLiteral() ast.Expression {
   495→	hash := &ast.HashLiteral{
   496→		Token: p.curToken,
   497→		Pairs: make(map[ast.Expression]ast.Expression),
   498→	}
   499→
   500→	if p.peekToken.Type == token.RBRACE {
   501→		p.nextToken()
   502→		return hash
   503→	}
   504→
   505→	for {
   506→		p.nextToken()
   507→
   508→		// Handle identifier or string keys
   509→		var key ast.Expression
   510→		switch p.curToken.Type {
   511→		case token.IDENTIFIER:
   512→			key = &ast.Identifier{
   513→				Token: p.curToken,
   514→				Value: p.curToken.Literal,
   515→			}
   516→		case token.STRING:
   517→			key = &ast.StringLiteral{
   518→				Token: p.curToken,
   519→				Value: p.curToken.Literal,
   520→			}
   521→		case token.INT:
   522→			val, _ := strconv.ParseInt(p.curToken.Literal, 0, 64)
   523→			key = &ast.IntegerLiteral{
   524→				Token: p.curToken,
   525→				Value: val,
   526→			}
   527→		default:
   528→			p.errors = append(p.errors, fmt.Sprintf("expected identifier, string, or number as hash key, got %s", p.curToken.Type))
   529→			return nil
   530→		}
   531→
   532→		if !p.expectPeek(token.COLON) {
   533→			return nil
   534→		}
   535→
   536→		p.nextToken()
   537→		value := p.parseExpression(LOWEST)
   538→		if value == nil {
   539→			return nil
   540→		}
   541→
   542→		hash.Pairs[key] = value
   543→
   544→		if p.peekToken.Type != token.COMMA {
   545→			break
   546→		}
   547→		p.nextToken() // consume comma
   548→	}
   549→
   550→	if !p.expectPeek(token.RBRACE) {
   551→		return nil
   552→	}
   553→
   554→	return hash
   555→}
