   591→// parseFunctionParameters parses parameter list
   592→func (p *Parser) parseFunctionParameters() []*ast.Identifier {
   593→	identifiers := []*ast.Identifier{}
   594→
   595→	if p.peekToken.Type == token.RPAREN {
   596→		p.nextToken()
   597→		return identifiers
   598→	}
   599→
   600→	p.nextToken()
   601→
   602→	ident := &ast.Identifier{
   603→		Token: p.curToken,
   604→		Value: p.curToken.Literal,
   605→	}
   606→	identifiers = append(identifiers, ident)
   607→
   608→	for p.peekToken.Type == token.COMMA {
   609→		p.nextToken()
   610→		p.nextToken()
   611→
   612→		ident := &ast.Identifier{
   613→			Token: p.curToken,
   614→			Value: p.curToken.Literal,
   615→		}
   616→		identifiers = append(identifiers, ident)
   617→	}
   618→
   619→	if !p.expectPeek(token.RPAREN) {
   620→		return nil
   621→	}
   622→
   623→	return identifiers
   624→}
