   626→// parseExpressionList parses comma-separated expressions until terminator
   627→func (p *Parser) parseExpressionList(terminator token.TokenType) []ast.Expression {
   628→	list := []ast.Expression{}
   629→
   630→	if p.peekToken.Type == terminator {
   631→		p.nextToken()
   632→		return list
   633→	}
   634→
   635→	p.nextToken()
   636→	list = append(list, p.parseExpression(LOWEST))
   637→
   638→	for p.peekToken.Type == token.COMMA {
   639→		p.nextToken()
   640→		p.nextToken()
   641→		list = append(list, p.parseExpression(LOWEST))
   642→	}
   643→
   644→	if !p.expectPeek(terminator) {
   645→		return nil
   646→	}
   647→
   648→	return list
   649→}
   650→
   651→// expectPeek checks if next token is of expected type
   652→func (p *Parser) expectPeek(t token.TokenType) bool {
   653→	if p.peekToken.Type != t {
   654→		p.errors = append(p.errors, fmt.Sprintf("expected %s, got %s instead", t, p.peekToken.Type))
   655→		return false
   656→	}
   657→
   658→	p.nextToken()
   659→	return true
   660→}
   661→
   662→// curPrecedence returns precedence of current token
   663→func (p *Parser) curPrecedence() int {
   664→	if p, ok := precedences[p.curToken.Type]; ok {
   665→		return p
   666→	}
   667→
   668→	return LOWEST
   669→}
   670→
   671→// peekPrecedence returns precedence of next token
   672→func (p *Parser) peekPrecedence() int {
   673→	if p, ok := precedences[p.peekToken.Type]; ok {
   674→		return p
   675→	}
   676→
   677→	return LOWEST
   678→}
